return {
    ["“正义”小姐赠予的钱包，沉甸甸的，里面装着价值不菲的金钱。"] = "Кошелек, подаренный Мисс Джастис, тяжелый и наполненный ценными деньгами.",
    ["亲爱的非凡者：\n恭喜您的等级达到38级！我们为您准备了等级奖励，用于版本测试升级养成使用，请查收！祝愿您在诡秘世界冒险愉快！"] = "Уважаемый Потусторонний!\nПоздравляем с достижением 38-го уровня! Мы подготовили для вас награды за уровень для тестирования улучшений в этой версии, заберите их! Желаем увлекательных приключений в мире «Повелителя Тайн»!",
    ["亲爱的非凡者：\n恭喜您的等级达到59级！我们为您准备了等级奖励，用于版本测试升级养成使用，请查收！祝愿您在诡秘世界冒险愉快！"] = "Уважаемый Потусторонний!\nПоздравляем с достижением 59-го уровня! Для тестирования игровых механик и развития персонажа мы подготовили для вас специальную награду за уровень. Приятных вам приключений в мире «Повелителя Тайн»!",
    ["亲爱的非凡者：\n恭喜您的等级达到62级！我们为您准备了等级奖励，用于版本测试升级养成使用，请查收！祝愿您在诡秘世界冒险愉快！"] = "Уважаемый Потусторонний!\nПоздравляем с достижением 62-го уровня! Мы подготовили для вас награды за уровень для тестирования улучшений в этой версии, заберите их! Желаем увлекательных приключений в мире «Повелителя Тайн»!",
    ["体验副本、竞技、探索等各种玩法以获取装备。"] = "Проходите подземелья, участвуйте в PvP и исследуйте мир, чтобы добыть снаряжение.",
    ["体验各类玩法以获取封印物。"] = "Участвуйте в различных режимах игры, чтобы получать Запечатанные Артефакты.",
    ["使用后从下列35品金色装备任意自选一款获得，部位包括武器、胸针、鞋靴、护甲、披风、护符。"] = "После использования выберите одну часть снаряжения золотого уровня 35-го уровня из следующих вариантов. Доступные слоты включают оружие, броши, ботинки, доспехи, плащи и амулеты.",
    ["使用后从下列60品金色装备任意自选一款获得，部位包括武器、胸针、鞋靴、护甲、披风、护符、帽子、指环。"] = "После использования выберите одну часть снаряжения золотого уровня 60-го уровня из следующих вариантов. Доступные слоты включают оружие, броши, ботинки, доспехи, плащи, амулеты, шляпы и кольца.",
    ["使用后从下列外观任意自选一款获得。"] = "После использования выберите и получите одно косметическое средство из следующего списка.",
    ["使用后可以在蠕动的饥饿、生物毒素瓶、月亮纸人中选择一个封印物获得。"] = "После использования вы можете выбрать один запечатанный артефакт из «Ползучего голода», «Бутылки с биологическим ядом» или «Лунной бумажной фигурки».",
    ["使用后可自选获得下列道具之一"] = "После использования вы можете выбрать один из следующих предметов для получения.",
    ["使用后可获得2个<Highlight>转运水晶</>，并有一定概率额外获得1个<Highlight>圣杯·绑</>。"] = "При использовании даёт 2 шт. <Highlight>кристаллов удачи</> с некоторой вероятностью дополнительно получить 1 шт. <Highlight>Священного Грааля (прив.)</>.",
    ["使用后可获得<Highlight>发型·不灭华焰</>和<Highlight>顶饰·不朽永燃</>\n也可兑换为<Highlight>2</>张神眷牌"] = "При использовании даёт <Highlight>причёску «Неугасимое яркое пламя»</> и <Highlight>украшение для волос «Вечно горящее бессмертие»</>.\nТакже можно обменять на <Highlight>2</> карты благословения богов.",
    ["使用后可获得<Highlight>展台·启示之间</>和<Highlight>组件·命运有形</>\n也可兑换为<Highlight>1</>张神眷牌"] = "После использования вы получите <Highlight>витрину «Зал откровения»</> и <Highlight>компонент «Осязаемая судьба»</>\nТакже можно обменять на <Highlight>1</> Карту Божьей милости",
    ["使用后可获得<Highlight>活力方糖</>2个以及<Highlight>300金镑代金券</>1个。"] = "Используйте, чтобы получить <Highlight>Кусочек сахара бодрости</> (2 шт.) и <Highlight>Купон на 300 золотых фунтов</> (1 шт.).",
    ["使用后可获得对应途径的序列时装（30天），晋升序列8后可升级为永久时装。"] = "После использования вы можете получить экипировку Последовательности для соответствующего Пути (30 дней). После перехода к 8-й последовательности его можно улучшить до постоянного наряда.",
    ["使用后可获得随机地图的传说灵线1个、金纺线3个，并有概率额外获得历史明灯1个。"] = "Использование этого дает 1 Легендарную линию духа для случайной карты и 3 Золотые нити с шансом дополнительно получить 1 Исторический маяк.",
    ["使用后可额外恢复活力值<Highlight>300</>，参与<Highlight>世界冒险、以战养战、教团等</>玩法后，可获得对应秘宝，消耗活力开启获得对应奖励。"] = "После использования восстанавливает дополнительно <Highlight>300</> ед. бодрости. Участвуя в режимах <Highlight>«Приключения в мире», «Война войной», «Культ» и др.</>, можно получить соответствующие сокровища, открываемые за бодрость для получения наград.",
    ["使用后增加1点<Highlight>丰饶之树</>副本的<Highlight>外观讨伐进度</>，外观讨伐进度达一定值后可获得1件该副本内的随机普通外观"] = "После использования увеличивает прогресс завоевания <Highlight>Appearance </> для подземелья <Highlight>Tree of Abundance</> на 1 очко. Как только прогресс достигнет определенного значения, вы сможете получить 1 случайный обычный облик из этого подземелья.",
    ["使用后增加1点<Highlight>五月庄园城堡</>副本的<Highlight>外观讨伐进度</>，外观讨伐进度达一定值后可获得1件该副本内的随机普通外观"] = "После использования увеличивает <Highlight>Внешний прогресс завоевания </> для подземелья <Highlight>May Manor · Castle</> на 1 очко. Как только прогресс достигнет определенного значения, вы сможете получить 1 случайный обычный облик из этого подземелья.",
    ["使用后增加1点<Highlight>五月庄园花园</>副本的<Highlight>外观讨伐进度</>，外观讨伐进度达一定值后可获得1件该副本内的随机普通外观"] = "После использования увеличивает прогресс завоевания <Highlight>Appearance Conquest </> для подземелья <Highlight>May Manor · Garden</> на 1 очко. Как только прогресс достигнет определенного значения, вы сможете получить 1 случайный обычный облик из этого подземелья.",
    ["使用后增加1点<Highlight>安提哥努斯笔记</>副本的<Highlight>外观讨伐进度</>，外观讨伐进度达一定值后可获得1件该副本内的随机普通外观"] = "После использования увеличивает <Highlight>Appearance Conquest Progress</> для подземелья <Highlight>Антигон Notebook</> на 1 очко. Как только прогресс достигнет определенного значения, вы сможете получить 1 случайный обычный облик из этого подземелья.",
    ["使用后将根据性别自动获得下列外观部件"] = "После использования вы автоматически получите следующие косметические детали в зависимости от вашего пола.",
    ["使用后将根据性别自动获得下列头像"] = "После его использования вы автоматически получите следующий аватар в зависимости от вашего пола.",
    ["使用后将获得下列外观部件。"] = "Используйте для получения следующих косметических деталей.",
    ["使用后概率获得35装等的金色装备。"] = "При использовании есть шанс получить золотое снаряжение 35-го уровня.",
    ["使用后获得1件35装等的金色装备，会根据当前已穿戴装备，获得提升最大的装备。"] = "После использования получите одну часть снаряжения золотого уровня 35-го уровня. Он предоставит оборудование, которое предлагает наибольшие улучшения на основе вашего текущего снаряжения.",
    ["使用后获得1件60装等橙色装备，会根据当前已穿戴装备，获得提升最大的装备。"] = "После использования вы получите 1 часть оранжевого снаряжения 60-го уровня. Это будет тот предмет, который обеспечит максимальное улучшение вашего текущего снаряжения.",
    ["使用后获得1件64装等橙色装备，会根据当前已穿戴装备，获得提升最大的装备。"] = "При использовании дает 1 предмет оранжевого снаряжения 64-го ур. снаряжения, который дает наибольшее улучшение с учетом текущей экипировки.",
    ["使用后获得500000绑定苏勒。"] = "После использования вы получите 500000 привязанных сулеров.",
    ["使用后获得5个聚合因子，可用于非凡材料聚合。"] = "После использования получают 5 факторов полимеризации, которые можно использовать для экстраординарной полимеризации материала.",
    ["使用后获得一个魔药材料。"] = "Используйте, чтобы получить материал для зелья.",
