    ["使用后解锁<Highlight>单人动作·助威</>，重复获取使用后自动分解为绑定苏勒。"] = "После использования разблокируйте одиночное действие <Highlight>: Cheer</>. Если его получить повторно, он будет автоматически разобран на связанный Сол при использовании.",
    ["使用后解锁<Highlight>单人动作·害怕</>，重复获取使用后自动分解为绑定苏勒。"] = "После использования разблокируйте одиночное действие <Highlight>: Fear</>. Если его получить повторно, он будет автоматически разобран на связанный Сол при использовании.",
    ["使用后解锁<Highlight>单人动作·欢喜</>，重复获取使用后自动分解为绑定苏勒。"] = "После использования разблокируйте индивидуальное действие <Highlight>: Joy</>. Если его получить повторно, он будет автоматически разобран на связанный Сол при использовании.",
    ["使用后解锁<Highlight>单人动作·祈祷</>，重复获取使用后自动分解为绑定苏勒。"] = "При использовании разблокирует одиночную эмоцию <Highlight>«Молитва»</>. При повторном получении автоматически распыляется на персональные соли.",
    ["使用后随机获得一件高品阶的装备"] = "После использования случайным образом получите одну часть высокоуровневого снаряжения.",
    ["使用后，可以从以下<Highlight>橙色秘偶碎片</>中选择一个获得。"] = "После использования вы можете выбрать один из следующих фрагментов оранжевой марионетки <Highlight> </> для получения.",
