    ["可随机获得1件<Highlight>冒险倾向</>装备，装等随赛季开启时间逐步提升。"] = "Можно случайным образом получить 1 предмет снаряжения <Highlight>склонности к приключениям</>. Уровень предмета постепенно растёт по мере хода сезона.",
    ["哥温顿二世继位后发行的新货币。经过改革，鲁恩人民的人均收入听起来都提高了不少。"] = "Новая валюта, выпущенная после восшествия на престол Георга III. После реформ средний доход народа Лоен, похоже, значительно увеличился.",
    ["墨绿泛白的钞票，是鲁恩王国货币体系中较为常见的货币。"] = "Темно-зеленые и белые банкноты, общая валюта денежной системы Королевства Лоен.",
    ["多数祈求只会归于沉默，但若祂真的回应，凡物也将拥有近乎神迹的价值。"] = "Большинство молитв заканчиваются молчанием, но если Он действительно ответит, то смертные предметы также будут обладать ценностью, граничащей с чудесами.",
    ["完成奉献后获得的感谢。\n付出已获铭记，此乃命运给予的必然赠礼。"] = "Благодарность, полученная после совершения подношения.\nВаши труды не забыты — таков неизбежный дар, ниспосланный самой судьбой.",
    ["完成奉献后追加的馈赠。\n付出愈丰铭记愈深，此乃命运给予的丰厚加赠。"] = "Дополнительный дар после совершения подношения.\nЧем щедрее дар, тем глубже память: такова щедрая награда, ниспосланная судьбой.",
    ["完成小组赛阶段，可获得以下奖励。"] = "Завершите групповой этап, чтобы получить следующие награды.",
    ["完成每轮小组赛，可获得以下基础奖励。"] = "Завершите каждый раунд группового этапа, чтобы получить следующие базовые награды.",
    ["完成轻松躺赢任务，获得对应类型的秘宝进度，每<Highlight>20进度</>获得1个养成资源箱。"] = "Выполняйте задания легкой победы, чтобы получать очки прогресса сокровищ соответствующего типа; за каждые <Highlight>20 очков прогресса</> даётся 1 сундук ресурсов развития.",
    ["宝箱，传说蕴含着神奇的力量。"] = "Сундук с сокровищами. Легенда гласит, что в нём сокрыта чудесная сила.",
    ["带有词条<Highlight><催眠师></>：“控制命中提升。”的攻击<Highlight>异变物质</>。"] = "Атака <Highlight> изменила материал </> с записью <Highlight><Гипнотизёр></>: «Частота попаданий по контролю увеличена».",
    ["带有词条<Highlight><天灾化身></>：“所有技能等级+1，暴击提升。”的攻击<Highlight>异变物质</>。"] = "Атакуйте <Highlight> мутировавшее вещество </> с записью <Highlight><天灾化身></>: «Все уровни навыков +1, критический удар увеличен».",
    ["带有词条<Highlight><守护者></>：“体质提升。”的防守<Highlight>异变物质</>。"] = "Защитный <Highlight>Мутированный материал</> с записью <Highlight><Guardian></>: «Телосложение увеличилось».",
    ["带有词条<Highlight><恐惧主教></>：“所有技能等级+1，技能增强提升。”的攻击<Highlight>异变物质</>。"] = "Атакуйте <Highlight> мутировавшее вещество </> с помощью записи <Highlight><恐惧主教></>: «Все уровни навыков +1, улучшение навыков».",
    ["带有词条<Highlight><愚者></>：“使封印物负面效果失效，所有技能等级+1，伤害减免提升。”的防守<Highlight>异变物质</>。"] = "Защитная <Highlight>мутировавшая материя</> со свойством <Highlight><Шут></>: «Нейтрализует отрицательные эффекты Запечатанных Артефактов, повышает уровень всех навыков на 1, увеличивает снижение урона».",
    ["带有词条<Highlight><愚者></>：“使封印物负面效果失效，所有技能等级+1，伤害加深提升。”的攻击<Highlight>异变物质</>。"] = "Атакуйте <Highlight>Мутировавшее вещество</> с аффиксом <Highlight><Шут></>: «Отменяет негативные эффекты Запечатанного Артефакта, все уровни навыков +1, усиление урона увеличено».",
    ["带有词条<Highlight><战争主教></>：“所有技能等级+1，攻击提升。”的攻击<Highlight>异变物质</>。"] = "Атака <Highlight> изменила материал </> с записью <Highlight><War Bishop></>: «Все уровни навыков +1, усиление атаки».",
    ["带有词条<Highlight><收割者></>：“力量/智慧提升。”的攻击<Highlight>异变物质</>。"] = "Атака <Highlight>Мутированный материал</> с записью <Highlight><Жнец></>: «Сила/Мудрость увеличена».",
    ["带有词条<Highlight><教唆者></>：“控制闪避提升。”的防守<Highlight>异变物质</>。"] = "Защитный <Highlight>Мутантный материал</> с записью <Highlight><Instigator></>: «Уклонение от контроля увеличено».",
    ["带有词条<Highlight><无暗者></>：“意志提升。”的防守<Highlight>异变物质</>。"] = "Защитный <Highlight> изменил материал </> с записью <Highlight><The Unshadowed></>: «Увеличенная сила воли».",
    ["带有词条<Highlight><格斗家></>：“格挡提升。”的防守<Highlight>异变物质</>。"] = "Защитный <Highlight>Мутированный материал</> с записью <Highlight><Fighter></>: «Блок увеличен».",
    ["带有词条<Highlight><沉默门徒></>：“所有技能等级+1，抗暴击提升。”的防守<Highlight>异变物质</>。"] = "Защита <Highlight>Мутированный материал</> с аффиксом <Highlight><Silent Disciple></>: «Все уровни навыков +1, антикритический удар увеличен».",
    ["带有词条<Highlight><混乱行者></>：“所有技能等级+1，生命提升。”的防守<Highlight>异变物质</>。"] = "Защитный <Highlight>Мутированный материал</> с записью <Highlight><Chaos Walker></>: «Все уровни навыков +1, здоровье увеличено».",
